export type MapBaseLayerKey = 'china' | 'china_alt' | 'osm';

export const MAP_BASE_LAYER_STORAGE_KEY = 'platform.map.baseLayer.v2';

export function readStoredMapBaseLayer(): MapBaseLayerKey {
  if (typeof window === 'undefined') {
    return 'china';
  }
  const storedValue = window.localStorage.getItem(MAP_BASE_LAYER_STORAGE_KEY);
  if (storedValue === 'china' || storedValue === 'china_alt' || storedValue === 'osm') {
    return storedValue;
  }
  return 'china';
}

export function persistMapBaseLayer(nextValue: MapBaseLayerKey): void {
  if (typeof window === 'undefined') {
    return;
  }
  window.localStorage.setItem(MAP_BASE_LAYER_STORAGE_KEY, nextValue);
}

def _validate_geojson_polygon(
    geometry_type: str,
    geometry: dict[str, Any],
) -> tuple[dict[str, Any], list[float]]:
    if not isinstance(geometry, dict):
        raise ValueError("geometry must be a GeoJSON object.")
    if str(geometry.get("type", "")).strip() != "Polygon":
        raise ValueError("Only GeoJSON Polygon geometries are supported.")

    coordinates = geometry.get("coordinates")
    if not isinstance(coordinates, list) or not coordinates:
        raise ValueError("Polygon coordinates are required.")

    first_ring = coordinates[0]
    if not isinstance(first_ring, list) or len(first_ring) < 4:
        raise ValueError("Polygon must contain at least four coordinate pairs.")

    for point in first_ring:
        lon = float(point[0])
        lat = float(point[1])
        if not (isfinite(lon) and isfinite(lat)):
            raise ValueError("Geometry coordinates must be finite numbers.")
        if not -180 <= lon <= 180:
            raise ValueError("Longitude must be within [-180, 180].")

